 ["Vibration schema"] = "Vibrationsschema",
 ["Visceral physical game-feel. Armor-weighted footstep gait, terrain landings, parry and block impacts, swimming drag, weather, and rich world looting."] = "Intensives physisches Spielgefühl. Rüstungsgewichteter Schrittgang, Landungen im Gelände, Parade- und Blockaufprälle, Schwimmwiderstand, Wetter und detailreiche Beute-Interaktionen.",
 ["Voice-coil actuators (LRA), ultra-low 0.025 floor, instant response"] = "Schwingspulen-Aktuatoren (LRA), extrem niedrige Losbrechschwelle von 0,025, sofortiges Ansprechverhalten",
 ["Walk cadence (steps/s)"] = "Gehkadenz (Schritte/s)",
 ["Warlock"] = "Hexenmeister",
 ["Warning lead time"] = "Warn-Vorlaufzeit",
 ["Warrior"] = "Krieger",
 ["Watches UNIT_TARGET and target swaps for hostile units whose target is the player. Uses UnitIsUnit('targettarget', 'player') with defensive secrecy guards."] = "Überwacht UNIT_TARGET und Zielwechsel feindlicher Einheiten, deren Ziel der Spieler ist. Verwendet UnitIsUnit('targettarget', 'player') mit defensiven Schutzprüfungen.",
 ["Water presence"] = "Wasserpräsenz",
 ["Wave cycle (seconds)"] = "Wellenzyklus (Sekunden)",
